const crypto = await import("node:crypto");
const fs = await import("node:fs");
const lean = "tmp/sheaf/xif/paper/S1929LiteralIQCarrierActual.lean";
const olean = ".lake/build/lib/lean/tmp/sheaf/xif/paper/S1929LiteralIQCarrierActual.olean";
const b = fs.readFileSync(lean);
const sha = crypto.createHash("sha256").update(b).digest("hex");
console.log("lean exists", fs.existsSync(lean), "bytes", b.length);
console.log("lean sha256", sha);
console.log("olean exists", fs.existsSync(olean), "bytes", fs.existsSync(olean) ? fs.statSync(olean).size : -1);
if (fs.existsSync(olean)) {
  const ob = fs.readFileSync(olean);
  console.log("olean sha256", crypto.createHash("sha256").update(ob).digest("hex"));
}
const txt = b.toString("utf8");
for (const tok of ["sorry", "admit", "axiom ", "True", "PUnit"]) {
  const idx = txt.indexOf(tok);
  console.log(tok, idx >= 0 ? `found at ${idx}` : "not found");
}
const lines = txt.split(/\r?\n/);
console.log("lines", lines.length);
", "description": "Compute SHA and check no sorry/axiom"}

